select r.id,s.id,r.name,r.description,null,r.image,r.section,true,r.translations
from jsonb_to_recordset($products$[{"id": "7b99e91b-00ad-5e84-88e2-c5710a5a583f", "name": "ديكور سائل أزرق بشكل ساعة رملية", "description": "قطعة ديكور شفافة بشكل ساعة رملية، بسائل أزرق وتفاصيل وشخصيات صغيرة.", "section": "ديكورات وهدايا", "image": "https://damascus-shop.com/images/happy-house/20261101/29935.jpg", "translations": {"en": {"name": "Blue liquid hourglass decoration"}, "de": {"name": "Blaue Flüssigkeits-Sanduhr als Dekoration"}}}, {"id": "e1339ea4-2127-55e5-8dc6-ef58c5ab58e7", "name": "طقم ضيافة فضي مزخرف", "description": "طقم ضيافة باللون الفضي، يضم إبريقًا وصينية وكؤوسًا بتفاصيل وزخارف متناسقة.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/29938.jpg", "translations": {"en": {"name": "Ornate silver-coloured serving set"}, "de": {"name": "Verziertes silberfarbenes Servierset"}}}, {"id": "f31a093a-1c2e-5cb1-b3de-9dd527e0fa43", "name": "منظم رفوف بنفسجي — ٤ طبقات", "description": "منظم بأربع سلال مفتوحة باللون البنفسجي مع أعمدة بيضاء، لترتيب الأغراض المنزلية.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/29930.jpg", "translations": {"en": {"name": "Purple storage rack — 4 tiers"}, "de": {"name": "Violettes Aufbewahrungsregal — 4 Ebenen"}}}, {"id": "2bd33eb9-3867-59c5-a8fb-7009738a9064", "name": "طقم ضيافة ذهبي وأسود مزخرف", "description": "طقم ضيافة بلون ذهبي وأسود، يضم إبريقًا وصينية وكؤوسًا بزخارف متناسقة.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/29933.jpg", "translations": {"en": {"name": "Ornate gold-and-black serving set"}, "de": {"name": "Verziertes gold-schwarzes Servierset"}}}, {"id": "0fa2904f-d047-5e65-971b-816c4b5d2fab", "name": "حامل مصحف مزخرف بقاعدة", "description": "حامل قراءة بلون خشبي، مع لوحة مائلة وقاعدة وزخارف وعبارة القرآن الكريم.", "section": "مستلزمات دينية", "image": "https://damascus-shop.com/images/happy-house/20261101/29928.jpg", "translations": {"en": {"name": "Decorative Quran reading stand"}, "de": {"name": "Verzierter Koran-Leseständer"}}}, {"id": "351d8ddf-a5ee-536f-b9f6-2be04d22d30c", "name": "منظم رفوف بيج — ٥ طبقات", "description": "منظم بخمس سلال مفتوحة باللون البيج، لترتيب الأغراض المنزلية واستغلال المساحة.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/29925.jpg", "translations": {"en": {"name": "Beige storage rack — 5 tiers"}, "de": {"name": "Beiges Aufbewahrungsregal — 5 Ebenen"}}}, {"id": "dd8b1838-1466-5675-a6d3-d133fb6ed92e", "name": "ديكور سائل أحمر بشكل قلبين", "description": "قطعة ديكور شفافة بشكل قلبين متجاورين، بسائل أحمر وتفاصيل قلوب صغيرة.", "section": "ديكورات وهدايا", "image": "https://damascus-shop.com/images/happy-house/20261101/29920.jpg", "translations": {"en": {"name": "Red liquid double-heart decoration"}, "de": {"name": "Rote Flüssigkeitsdekoration mit zwei Herzen"}}}, {"id": "8d21da7e-75cf-530b-aa75-3d41901014bb", "name": "شمعدان ذهبي ثلاثي مزخرف", "description": "حامل شموع بثلاثة أذرع باللون الذهبي، مع حوامل زجاجية وتفاصيل زخرفية شفافة.", "section": "ديكورات وهدايا", "image": "https://damascus-shop.com/images/happy-house/20261101/29923.jpg", "translations": {"en": {"name": "Ornate gold-coloured three-arm candle holder"}, "de": {"name": "Verzierter goldfarbener Kerzenhalter mit drei Armen"}}}]$products$::jsonb)
as r(id uuid,name text,description text,section text,image text,translations jsonb)
cross join public.stores s where s.id='c0a627c1-229d-4da9-957c-4aff3ff48a8f' and s.active and s.deleted_at is null
on conflict(id) do nothing;
commit;
